import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/13-Transport_Design.html","title":"Apollo 进程间通信 Transport 设计","lang":"en-US","frontmatter":{},"filePathRelative":"13-Transport_Design.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`13-Transport_Design.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="apollo-进程间通信-transport-设计" tabindex="-1"><a class="header-anchor" href="#apollo-进程间通信-transport-设计"><span>Apollo 进程间通信 Transport 设计</span></a></h1><blockquote><p>目标：抽象服务器之间的通信方式（TCP/IP、IPC、共享内存……），支持能力注册、优先级选择、QoS/背压配置。当前实现基于 NNG，接口预留未来扩展。</p></blockquote><h2 id="_1-设计原则" tabindex="-1"><a class="header-anchor" href="#_1-设计原则"><span>1. 设计原则</span></a></h2><ol><li><strong>能力协商</strong>：每个进程声明自己支持的 transport 列表（协议、地址、优先级、属性），对端根据本地能力自动选择最佳方案。</li><li><strong>统一接口</strong>：业务层只依赖 <code>ITransport</code>、<code>IConnection</code>、<code>IListener</code>，无需关心 NNG/TCP/SHM 的细节。</li><li><strong>可扩展</strong>：初期实现 <code>nng-tcp</code>、<code>nng-ipc</code>，未来可补充共享内存、Relay、KCP 等协议，而无需修改业务代码。</li><li><strong>QoS/背压</strong>：连接对象需暴露高水位线、队列长度、统计指标；注册信息可描述带宽/延迟，供调度器参考。</li></ol><h2 id="_2-transport-接口" tabindex="-1"><a class="header-anchor" href="#_2-transport-接口"><span>2. Transport 接口</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">struct</span> <span class="token class-name">TransportEndpoint</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string protocol<span class="token punctuation">;</span>    <span class="token comment">// e.g. &quot;nng-tcp&quot;, &quot;nng-ipc&quot;, &quot;shm&quot;</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string address<span class="token punctuation">;</span>     <span class="token comment">// &quot;tcp://10.0.0.5:6100&quot;, &quot;ipc://zone-1.ipc&quot;</span></span>
<span class="line">    <span class="token keyword">int</span> priority <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">;</span>      <span class="token comment">// 越小越优先</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>map<span class="token operator">&lt;</span>std<span class="token double-colon punctuation">::</span>string<span class="token punctuation">,</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&gt;</span> attributes<span class="token punctuation">;</span> <span class="token comment">// latency/bandwidth/locality…</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">IConnection</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token operator">~</span><span class="token function">IConnection</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">Send</span><span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token keyword">void</span><span class="token operator">*</span> data<span class="token punctuation">,</span> size_t len<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">Recv</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token operator">*</span> buffer<span class="token punctuation">,</span> size_t<span class="token operator">*</span> len<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 背压/QoS</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">SetHighWaterMark</span><span class="token punctuation">(</span>size_t messages<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">SetPriority</span><span class="token punctuation">(</span><span class="token keyword">int</span> priority<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> ConnectionStats <span class="token function">GetStats</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">IListener</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token operator">~</span><span class="token function">IListener</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">Start</span><span class="token punctuation">(</span>std<span class="token double-colon punctuation">::</span>function<span class="token operator">&lt;</span><span class="token keyword">void</span><span class="token punctuation">(</span>std<span class="token double-colon punctuation">::</span>unique_ptr<span class="token operator">&lt;</span>IConnection<span class="token operator">&gt;</span><span class="token punctuation">)</span><span class="token operator">&gt;</span> onAccept<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">Stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">ITransport</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token operator">~</span><span class="token function">ITransport</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> std<span class="token double-colon punctuation">::</span>string <span class="token function">Name</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">CanDial</span><span class="token punctuation">(</span><span class="token keyword">const</span> TransportEndpoint<span class="token operator">&amp;</span> ep<span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> std<span class="token double-colon punctuation">::</span>unique_ptr<span class="token operator">&lt;</span>IConnection<span class="token operator">&gt;</span> <span class="token function">Dial</span><span class="token punctuation">(</span><span class="token keyword">const</span> TransportEndpoint<span class="token operator">&amp;</span> ep<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">bool</span> <span class="token function">CanListen</span><span class="token punctuation">(</span><span class="token keyword">const</span> TransportEndpoint<span class="token operator">&amp;</span> ep<span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">virtual</span> std<span class="token double-colon punctuation">::</span>unique_ptr<span class="token operator">&lt;</span>IListener<span class="token operator">&gt;</span> <span class="token function">Listen</span><span class="token punctuation">(</span><span class="token keyword">const</span> TransportEndpoint<span class="token operator">&amp;</span> ep<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="默认实现-v1" tabindex="-1"><a class="header-anchor" href="#默认实现-v1"><span>默认实现（v1）</span></a></h3><ul><li><code>NNGTcpTransport</code>：使用 NNG TCP transport (<code>tcp://host:port</code>)，跨服务器通信默认使用。</li><li><code>NNGIPCTransport</code>：使用 NNG IPC（Linux: Unix socket；Windows: 命名管道），同机通信优先。</li><li><code>ShmTransport</code>：预留接口，但暂未实现；注册信息中可包含 <code>protocol: &quot;shm&quot;</code> 以方便后续。</li></ul><h3 id="背压-统计" tabindex="-1"><a class="header-anchor" href="#背压-统计"><span>背压/统计</span></a></h3><ul><li><code>SetHighWaterMark</code> 映射到 NNG 的 <code>NNG_OPT_SENDBUF/NNG_OPT_RECVBUF</code> 或共享内存队列容量。</li><li><code>ConnectionStats</code> 包含：发送/接收消息数、队列长度、最后延迟、重连次数等，供监控和调度使用。</li></ul><h2 id="_3-服务注册与能力描述" tabindex="-1"><a class="header-anchor" href="#_3-服务注册与能力描述"><span>3. 服务注册与能力描述</span></a></h2><h3 id="注册信息结构" tabindex="-1"><a class="header-anchor" href="#注册信息结构"><span>注册信息结构</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;server_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1-2-6-1&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;service&quot;</span><span class="token operator">:</span> <span class="token string">&quot;ZoneServer&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;host&quot;</span><span class="token operator">:</span> <span class="token string">&quot;10.0.0.5&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;transports&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;nng-ipc&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;ipc://zone-1.ipc&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;attributes&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;locality&quot;</span><span class="token operator">:</span> <span class="token string">&quot;same-host&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;latency&quot;</span><span class="token operator">:</span> <span class="token string">&quot;low&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;max_msg_bytes&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1048576&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;nng-tcp&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;tcp://10.0.0.5:6100&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">10</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;attributes&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;bandwidth&quot;</span><span class="token operator">:</span> <span class="token string">&quot;high&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;latency&quot;</span><span class="token operator">:</span> <span class="token string">&quot;medium&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;metadata&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;process&quot;</span><span class="token operator">:</span> <span class="token string">&quot;zone_server&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1.0.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;heartbeat&quot;</span><span class="token operator">:</span> <span class="token number">1717830000</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="注册流程" tabindex="-1"><a class="header-anchor" href="#注册流程"><span>注册流程</span></a></h3><ol><li>进程启动后，构建自己的 <code>TransportEndpoint</code> 列表（至少一个）。</li><li>调用 ServiceRegistry（Consul/Etcd/ZK）注册，并定期刷新心跳。后续可支持本地文件/Envoy LDS 等方式。</li><li>若 transport 配置变更（如 IPC 文件重命名、端口变化），需更新注册信息。</li></ol><h3 id="消费流程" tabindex="-1"><a class="header-anchor" href="#消费流程"><span>消费流程</span></a></h3><ol><li>调用 ServiceDiscovery 查询目标服务，获取其 transport 列表。</li><li>结合本地 transport 能力和 <code>priority</code>/<code>attributes</code> 按优先级排序： <ul><li>同机 → 使用 <code>nng-ipc</code></li><li>同机且共享内存可用 → 将来可尝试 <code>shm</code></li><li>跨机 → fallback <code>nng-tcp</code></li></ul></li><li>调用对应 <code>ITransport::Dial</code> 建立连接；若失败，继续尝试下一候选。</li><li>建立成功后，业务层只看 <code>IConnection</code> 接口；同时记录采用了哪种 transport 以便监控。</li></ol><h2 id="_4-能力协商与特性" tabindex="-1"><a class="header-anchor" href="#_4-能力协商与特性"><span>4. 能力协商与特性</span></a></h2><p>在 <code>Dial</code> 阶段可进行握手，交换如下信息：</p><ul><li><strong>最大消息大小</strong>：防止发送端超过接收端承受能力。</li><li><strong>批量/合并包能力</strong>：决定是否开启批量发送或零拷贝。</li><li><strong>安全属性</strong>：是否启用加密/签名（可选）。</li><li><strong>扩展特性</strong>：例如压缩、共享内存通道、Relay 支持等。</li></ul><p>协商方式：在第一次发送的数据帧中附带 <code>HandshakeFrame</code>，双方确认后进入正常数据帧模式。</p><h2 id="_5-监控与运维" tabindex="-1"><a class="header-anchor" href="#_5-监控与运维"><span>5. 监控与运维</span></a></h2><ul><li>每个连接统计项：吞吐、延迟、队列、重连次数、使用的 transport。</li><li>定期将统计信息上报到监控系统（Prometheus 或自研）。</li><li>当某 transport 异常（连接失败率高、延迟异常）时可自动降级或标记为 unhealthy，触发 ServiceRegistry 更新。</li><li>支持动态调整：例如命令行/GM 可在运行时重新设置某进程的可用 transport、优先级等。</li></ul><h2 id="_6-roadmap" tabindex="-1"><a class="header-anchor" href="#_6-roadmap"><span>6. Roadmap</span></a></h2><ol><li><strong>Phase 1</strong>：实现 <code>nng-tcp</code>、<code>nng-ipc</code> transport；接入服务注册/发现；支持优先级选择和基本背压。</li><li><strong>Phase 2</strong>：扩展 <code>shm</code> transport（共享内存 ring buffer + 控制通道）；定义握手协议、零拷贝接口。</li><li><strong>Phase 3</strong>：加上 Relay/加速 transport、QoS 策略、动态策略下发（如根据业务类型选择不同传输）。</li><li><strong>Phase 4</strong>：安全扩展（mutual TLS、ACL）和更完整的监控、调试工具。</li></ol><hr><p>本设计为后续通信框架的基础。短期内所有进程都使用 NNG transport，同时通过注册能力预留共享内存等更快的通道。下一步可在实施计划中加入“Transport 层开发”任务，并在 NetCore/AOI 等文档引用此设计。***</p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};